#!/usr/bin/env bash
# Enforce Conventional Commits on the subject line — the commit-msg hook.
#
# $1 is git's commit-message file. moon exports it as $ARG1 too, but the positional is what git
# itself passes and is the one that survives someone reading this out of context.
set -euo pipefail

subject=$(head -1 "$1")

# A comment-only first line means git will abort the commit itself (empty message), and a merge or
# revert message is generated by git rather than typed — refusing those is noise, not a gate.
[[ $subject == \#* ]] && exit 0
[[ $subject == Merge* || $subject == Revert* ]] && exit 0

if [[ ! $subject =~ ^(feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert)(\(.+\))?!?:\ .+ ]]; then
  echo "Commit message must follow Conventional Commits, e.g. 'feat: add platform invite flow'" >&2
  echo "  got: $subject" >&2
  exit 1
fi
